  "witnessCode": "import { test, strict as assert } from 'node:test'
import normalizeUrl from '../index.js'

test('normalizeUrl preserves charset attribute for default charset', () => {
  const input = 'data:text/plain;charset=us-ascii,hello'
  const expected = 'data:text/plain;charset,hello'
  assert.strictEqual(normalizeUrl(input), expected)
})"
